[CmdletBinding()]
param([Parameter(Mandatory)][string]$SourcePath,[Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop'
function Require([bool]$Condition,[string]$Message){if(-not $Condition){throw $Message}}
$item=Get-Item -LiteralPath $SourcePath -Force -ErrorAction Stop;Require (-not $item.PSIsContainer -and ($item.Attributes -band [IO.FileAttributes]::ReparsePoint)-eq 0 -and $item.Length -le 2097152) 'archive verifier source bound/reparse proof failed';$s=[IO.File]::ReadAllText($item.FullName)
foreach($needle in @('Read-BoundedJson','File-Proof','Receipt-Stream','observer.status','outer transport not passed','manifest hash join mismatch','launcher cleanup/exit proof incomplete','collector ownership/cleanup proof incomplete','coordinator parent/lock proof incomplete','qualificationPass','aggregateMemoryCapExceeded','parentOriginalHandleRetained','presentMonSessionAbsent','status=$status','strict-displayed-workload-and-process','Write-AtomicFresh')){Require ($s.Contains($needle)) "archive verifier control missing: $needle"}
Require ($s.Contains('8388608') -and $s.Contains('67108864') -and $s.Contains('2097152')) 'archive verifier bounds missing';Require ($s -notmatch 'Start-Process|Process\]::Start|Register-ScheduledTask|Start-ScheduledTask|Stop-Process|taskkill|Remove-Item|File\]::Delete') 'archive verifier launches or mutates processes/files'
$out=[ordered]@{kind='sr0-display-selfjob-v4-archive-verifier-source-controls-v1';status='passed-source-controls';sourcePath=[IO.Path]::GetFullPath($SourcePath);sourceBytes=$item.Length;nativeActions=0;processActions=0;mutationsRejected=0;checkedAt=[DateTimeOffset]::UtcNow.ToString('o')};$parent=Split-Path -Parent ([IO.Path]::GetFullPath($OutputPath));if(-not(Test-Path -LiteralPath $parent)){[IO.Directory]::CreateDirectory($parent)|Out-Null};$out|ConvertTo-Json -Depth 8|Set-Content -LiteralPath $OutputPath -Encoding UTF8;$out|ConvertTo-Json -Depth 8
